//! End-to-end coverage of the ONE static file walk every `static/*`
//! analyzer shares, driven through the **real binary** over hermetic trees
//! written into a tempdir.
//!
//! The walk contract under test (`cf_commands::handlers::walk_source_files`):
//!
//! * the generated-content marker (`Code generated … DO NOT EDIT` in the
//!   first 512 bytes) excludes a file from EVERY analyzer by default and
//!   `--include-generated` re-admits it — composition is the designed
//!   exception and classifies the file in both runs;
//! * `-a 'static/*'` reports the same per-analyzer numbers as the single
//!   runs, in json, yaml and bin;
//! * `--per-file` applies to `--format json` only and says so on stderr for
//!   any other format;
//! * an unreadable file is reported ONCE on stderr for the whole run;
//! * the output is a pure function of the tree and the flags.

mod common;

use std::fs;
use std::path::Path;

use serde_json::Value;

/// Path to the freshly built `codefang` binary under test.
const BIN: &str = env!("CARGO_BIN_EXE_codefang");

/// Every static analyzer, in the registry (merged-report section) order.
const STATIC_ANALYZERS: [&str; 7] = [
    "static/clones",
    "static/complexity",
    "static/comments",
    "static/halstead",
    "static/cohesion",
    "static/imports",
    "static/composition",
];

/// The one analyzer that classifies generated files instead of skipping them.
const COMPOSITION: &str = "static/composition";

/// The generated-file marker in the header of the fixture's `gen.go`.
const GENERATED_HEADER: &str = "// Code generated by protoc-gen-go. DO NOT EDIT.\n";

/// The stderr note printed when `--per-file` meets a non-json format.
const PER_FILE_NOTE_PREFIX: &str = "--per-file applies to --format json only; ignored for ";

/// The stderr line prefix of a skipped (unreadable / oversized) file.
const SKIPPED_PREFIX: &str = "warning: skipped ";

/// A plain Go file with one function (an `if`, so every analyzer has data).
const PLAIN_GO: &str =
    "package main\n\nimport \"fmt\"\n\n// plain is documented.\nfunc plain(a int) int {\n\tif a > 0 {\n\t\tfmt.Println(a)\n\t\treturn a\n\t}\n\treturn -a\n}\n";
/// The same function under a different name, in a nested directory.
const NESTED_GO: &str =
    "package sub\n\nfunc nested(b int) int {\n\tif b > 0 {\n\t\treturn b\n\t}\n\treturn -b\n}\n";
/// A vendored function.
const VENDOR_GO: &str =
    "package dep\n\nfunc vendored(c int) int {\n\tif c > 0 {\n\t\treturn c\n\t}\n\treturn -c\n}\n";
/// The function body of the generated file (the header is prepended).
const GEN_BODY: &str =
    "package main\n\nfunc generated(d int) int {\n\tif d > 0 {\n\t\treturn d\n\t}\n\treturn -d\n}\n";

fn write(dir: &Path, rel: &str, content: &str) {
    let path = dir.join(rel);
    fs::create_dir_all(path.parent().expect("parent")).expect("mkdir");
    fs::write(path, content).expect("write fixture");
}

/// The fixture: a plain file, a nested file, a vendored file, a file whose
/// HEADER carries the generated marker (its name is not a generated
/// pattern), a `.git` entry and an unsupported text file.
fn fixture() -> tempfile::TempDir {
    let dir = tempfile::tempdir().expect("tempdir");
    write(dir.path(), "a.go", PLAIN_GO);
    write(dir.path(), "sub/b.go", NESTED_GO);
    write(dir.path(), "vendor/dep.go", VENDOR_GO);
    write(
        dir.path(),
        "gen.go",
        &format!("{GENERATED_HEADER}{GEN_BODY}"),
    );
    write(dir.path(), ".git/x.go", PLAIN_GO);
    write(dir.path(), "notes.txt", "not source\n");
    dir
}

/// Runs `codefang run <args>` with a pinned environment.
fn codefang(args: &[&str]) -> std::process::Output {
    common::command(BIN)
        .arg("run")
        .args(args)
        .env("TZ", "UTC")
        .env("NO_COLOR", "1")
        .env("LANG", "C")
        .env("LC_ALL", "C")
        .output()
        .expect("run the codefang binary")
}

/// `(exit code, stdout, stderr)` of `-a <analyzer> --format <format> <extra> <path>`.
fn run(analyzer: &str, format: &str, extra: &[&str], path: &Path) -> (i32, Vec<u8>, String) {
    let p = path.to_str().expect("utf-8 path");
    let out = codefang(&[&["-a", analyzer, "--format", format], extra, &[p]].concat());
    (
        out.status.code().unwrap_or(-1),
        out.stdout,
        String::from_utf8_lossy(&out.stderr).into_owned(),
    )
}

/// The `--per-file` json report of one analyzer; exit 0 is asserted.
fn per_file_json(analyzer: &str, extra: &[&str], path: &Path) -> Value {
    let (code, stdout, stderr) = run(analyzer, "json", &[&["--per-file"], extra].concat(), path);
    assert_eq!(code, 0, "{analyzer} failed:\n{stderr}");
    serde_json::from_slice(&stdout).expect("json report parses")
}

/// The `file_path` values of the first section's `files` array.
fn file_paths(report: &Value) -> Vec<String> {
    report["sections"][0]["files"]
        .as_array()
        .expect("files array")
        .iter()
        .map(|f| f["file_path"].as_str().expect("file_path").to_string())
        .collect()
}

/// Every analyzer's `--per-file` list excludes the marker-generated file by
/// default and lists it with `--include-generated`; composition (which
/// exists to report generated shares) lists it both times. The `.git`
/// entry, the vendored file and the unsupported file never appear.
#[test]
fn generated_marker_is_applied_by_every_static_analyzer() {
    let dir = fixture();
    for analyzer in STATIC_ANALYZERS {
        let default = file_paths(&per_file_json(analyzer, &[], dir.path()));
        let included = file_paths(&per_file_json(
            analyzer,
            &["--include-generated"],
            dir.path(),
        ));
        assert!(
            default.iter().any(|p| p == "a.go") && default.iter().any(|p| p == "sub/b.go"),
            "{analyzer}: plain files missing from {default:?}"
        );
        assert!(
            !default.iter().any(|p| p.contains(".git")),
            "{analyzer}: .git walked: {default:?}"
        );
        if analyzer == COMPOSITION {
            assert!(
                default.iter().any(|p| p == "gen.go") && included.iter().any(|p| p == "gen.go"),
                "{analyzer}: composition must classify gen.go ({default:?} / {included:?})"
            );
            continue;
        }
        assert!(
            !default.iter().any(|p| p == "gen.go"),
            "{analyzer}: the generated marker was not applied: {default:?}"
        );
        assert!(
            included.iter().any(|p| p == "gen.go"),
            "{analyzer}: --include-generated did not re-admit gen.go: {included:?}"
        );
        assert!(
            !default.iter().any(|p| p.starts_with("vendor/")),
            "{analyzer}: vendored file analyzed: {default:?}"
        );
        assert!(
            !default.iter().any(|p| p == "notes.txt"),
            "{analyzer}: unsupported file analyzed: {default:?}"
        );
    }
}

/// The merged `static/*` json report carries each analyzer's section EXACTLY
/// as the single run renders it (registry order).
#[test]
fn multi_analyzer_json_sections_equal_the_single_runs() {
    let dir = fixture();
    let (code, stdout, stderr) = run("static/*", "json", &["--per-file"], dir.path());
    assert_eq!(code, 0, "merged run failed:\n{stderr}");
    let merged: Value = serde_json::from_slice(&stdout).expect("merged json parses");
    let sections = merged["sections"].as_array().expect("sections");
    assert_eq!(sections.len(), STATIC_ANALYZERS.len());
    for (section, analyzer) in sections.iter().zip(STATIC_ANALYZERS) {
        let single = per_file_json(analyzer, &[], dir.path());
        assert_eq!(
            section, &single["sections"][0],
            "{analyzer}: merged section differs from the single run"
        );
    }
}

/// `-a 'static/*'` in yaml and bin is the concatenation of the single runs.
#[test]
fn multi_analyzer_yaml_and_bin_equal_the_single_runs() {
    let dir = fixture();
    for format in ["yaml", "bin"] {
        let (code, merged, stderr) = run("static/*", format, &[], dir.path());
        assert_eq!(code, 0, "merged {format} run failed:\n{stderr}");
        let mut expected = Vec::new();
        for analyzer in STATIC_ANALYZERS {
            let (code, stdout, stderr) = run(analyzer, format, &[], dir.path());
            assert_eq!(code, 0, "{analyzer} {format} failed:\n{stderr}");
            expected.extend_from_slice(&stdout);
        }
        assert!(
            merged == expected,
            "{format}: merged output differs from the concatenated single runs"
        );
    }
}

/// `--per-file` is a json-only enrichment: every other format prints ONE
/// stderr note naming the format; json prints none.
#[test]
fn per_file_note_is_printed_once_for_non_json_formats() {
    let dir = fixture();
    for format in ["yaml", "bin"] {
        let (code, _stdout, stderr) = run("static/complexity", format, &["--per-file"], dir.path());
        assert_eq!(code, 0, "{format} run failed:\n{stderr}");
        let expected = format!("{PER_FILE_NOTE_PREFIX}{format}");
        assert_eq!(
            stderr.lines().filter(|l| *l == expected).count(),
            1,
            "{format}: expected one note {expected:?} in:\n{stderr}"
        );
    }
    // A multi-analyzer bin run prints the note once, not once per analyzer.
    let (code, _stdout, stderr) = run("static/*", "bin", &["--per-file"], dir.path());
    assert_eq!(code, 0, "{stderr}");
    assert_eq!(
        stderr
            .lines()
            .filter(|l| l.starts_with(PER_FILE_NOTE_PREFIX))
            .count(),
        1,
        "static/* bin: one note expected in:\n{stderr}"
    );
    let (code, _stdout, stderr) = run("static/complexity", "json", &["--per-file"], dir.path());
    assert_eq!(code, 0, "{stderr}");
    assert!(
        !stderr.contains(PER_FILE_NOTE_PREFIX),
        "json must not print the note:\n{stderr}"
    );
}

/// An unreadable file is skipped with ONE stderr warning for the whole
/// multi-analyzer run and counted once in the end-of-run summary.
#[test]
#[cfg(unix)]
fn unreadable_file_is_reported_once_per_run() {
    use std::os::unix::fs::PermissionsExt;

    let dir = fixture();
    let secret = dir.path().join("secret.go");
    fs::write(&secret, PLAIN_GO).expect("write secret");
    fs::set_permissions(&secret, fs::Permissions::from_mode(0o000)).expect("chmod");
    if fs::read(&secret).is_ok() {
        // Running as root: the file is readable regardless of its mode.
        return;
    }
    let (code, stdout, stderr) = run("static/*", "json", &["--per-file"], dir.path());
    assert_eq!(code, 0, "{stderr}");
    let warning = format!("{SKIPPED_PREFIX}{}: unreadable", secret.display());
    assert_eq!(
        stderr.lines().filter(|l| *l == warning).count(),
        1,
        "expected one warning {warning:?} in:\n{stderr}"
    );
    assert!(
        stderr.contains("progress: skipped 1 unreadable/oversized/unparseable files"),
        "end-of-run summary missing or wrong:\n{stderr}"
    );
    let merged: Value = serde_json::from_slice(&stdout).expect("json");
    let sections = merged["sections"].as_array().expect("sections");
    for (section, analyzer) in sections.iter().zip(STATIC_ANALYZERS) {
        let paths: Vec<&str> = section["files"]
            .as_array()
            .expect("files")
            .iter()
            .filter_map(|f| f["file_path"].as_str())
            .collect();
        // Composition classifies every file the walk reaches; an unreadable
        // one is classified on its path alone. Every source analyzer skips it.
        let listed = paths.contains(&"secret.go");
        assert_eq!(
            listed,
            analyzer == COMPOSITION,
            "{analyzer}: unexpected secret.go handling: {paths:?}"
        );
    }
}

/// The walk output is a pure function of the tree and the flags.
#[test]
fn static_walk_output_is_deterministic() {
    let dir = fixture();
    let first = run("static/*", "json", &["--per-file"], dir.path());
    let second = run("static/*", "json", &["--per-file"], dir.path());
    assert_eq!(first.0, 0, "{}", first.2);
    assert!(
        first.1 == second.1,
        "two identical runs produced different bytes"
    );
    let yaml_first = run("static/*", "yaml", &[], dir.path());
    let yaml_second = run("static/*", "yaml", &[], dir.path());
    assert!(yaml_first.1 == yaml_second.1, "yaml runs differ");
}
